// runtimes/codex.mjs
export const id = 'codex'

const json = value => `${JSON.stringify(value, null, 2)}\n`

function commandFile(skill) {
  const description = skill.description.replace(/\\/g, '\\\\').replace(/"/g, '\\"')
  return [
    '# Generated by no-vibe. Do not edit.',
    `description = "${description}"`,
    '',
    'prompt = """',
    `Invoke the \`${skill.name}\` skill and follow it exactly.`,
    '',
    'User intent: {{args}}',
    '"""',
    '',
  ].join('\n')
}

export function emit(model) {
  const { config, skills } = model
  const files = {
    // Codex fired no hooks from an inline hooks object in a 0.163.0 probe.
    // A path to hooks/hooks.json is the form that loads.
    '.codex-plugin/plugin.json': json({
      name: config.name,
      version: config.version,
      description: config.description,
      author: config.author,
      homepage: config.homepage,
      repository: config.repository,
      license: config.license,
      keywords: config.keywords,
      skills: './skills/',
      hooks: './hooks/hooks.json',
    }),
    '.agents/plugins/marketplace.json': json({
      name: config.name,
      interface: { displayName: config.name },
      plugins: [{
        name: config.name,
        source: { source: 'local', path: './' },
        policy: { installation: 'AVAILABLE', authentication: 'ON_INSTALL' },
        category: 'Learning',
      }],
    }),
  }
  for (const skill of skills.filter(s => s.command)) {
    files[`commands/${skill.name}.toml`] = commandFile(skill)
  }
  return files
}

export function ships() {
  return ['.agents/']
}
